ALTER TABLE Techniki ADD CONSTRAINT Techniki_Umiejętności_FK 
    FOREIGN KEY (Umiejętności_Nazwa) REFERENCES Umiejętności (Nazwa);

-- Techniki_uczone_z_ksiąg
ALTER TABLE Techniki_uczone_z_ksiąg
    ADD CONSTRAINT Techniki_uczone_z_ksiąg_Księgi_i_Pisma_FK 
        FOREIGN KEY (Księgi_i_Pisma_Przedmioty_Przed_Nazwa) 
        REFERENCES Księgi_i_Pisma (Przedmioty_Przed_Nazwa);
ALTER TABLE Techniki_uczone_z_ksiąg
    ADD CONSTRAINT Techniki_uczone_z_ksiąg_Techniki_FK 
        FOREIGN KEY (Techniki_nazwa)
        REFERENCES Techniki (nazwa);

