    FOREIGN KEY (Postacie_Imię, Postacie_Nazwisko) REFERENCES Postacie (Imię, Nazwisko);
ALTER TABLE zna ADD CONSTRAINT zna_Techniki_FK 
    FOREIGN KEY (Techniki_nazwa) REFERENCES Techniki (nazwa);


